ROOT=Path(__file__).resolve().parents[1];ENGINE=os.getenv('GIF_TEST_BROWSER','chromium');cm=json.loads((ROOT/'cmfit-catalog.json').read_text())['videos'];first=next(v for v in cm if v['name']=='Mobilidade gato e vaca');second=next(v for v in cm if v['name']=='Alongamento de posteriores da coxa');replacement=next(v for v in cm if v['name']=='Alongamento de posteriores com toalha');YT='https://youtu.be/preserve_YT';name=first['name']+' + '+second['name'];line=name+' — 1×15s + 1×10 [Vídeo: '+YT+'] [GIFs: '+first['url']+' | '+second['url']+']';extra='Alongamento de quadríceps — 1×15s'
